import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = defaultdict(set)
    deg = [0] * (n + 1)

    edges = []
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        if u > v:
            u, v = v, u
        adj[u].add(v)
        adj[v].add(u)
        deg[u] += 1
        deg[v] += 1
        edges.append((u, v))

    alice_triangles = 0

    for u, v in edges:
        common = 0
        if len(adj[u]) < len(adj[v]):
            for w in adj[u]:
                if w in adj[v]:
                    common += 1
        else:
            for w in adj[v]:
                if w in adj[u]:
                    common += 1
        alice_triangles += common // 2

    bob_deg = [n - 1 - d for d in deg]
    total_triangles_bob = 0

    for i in range(1, n + 1):
        d_a = deg[i]
        d_b = bob_deg[i]

        cnt_2_edges_in_bob = 0

        if d_b > 0:
            neighbors = adj[i]
            count_common = 0

            for j in neighbors:
                if deg[j] < deg[i]:
                    continue

                d_j_b = bob_deg[j]

                if d_j_b > 0:
                    common_neighbors = 0
                    if len(neighbors) < len(adj[j]):
                        for k in neighbors:
                            if k in adj[j]:
                                common_neighbors += 1
                    else:
                        for k in adj[j]:
                            if k in neighbors:
                                common_neighbors += 1

                    cnt_2_edges_in_bob += d_j_b - common_neighbors

            total_triangles_bob += cnt_2_edges_in_bob

    total_triangles_bob //= 2

    print(alice_triangles + total_triangles_bob)

if __name__ == "__main__":
    solve()
